      let quality = 1;
      if (metrics.hasFinish) quality += 1;
      if (metrics.hasSuccessFinish) quality += 1;
      if (metrics.productiveCalls > 0) quality += 1;
      if (metrics.totalCalls > 0 && metrics.errorRate < 0.2) quality += 1;

